import path from 'path';
import fs from 'fs';
import { log } from '../core/logger.js';
export async function initCommand() {
    const destination = path.resolve(process.cwd(), 'webapkify.config.ts');
    if (fs.existsSync(destination)) {
        log.warn('webapkify.config.ts already exists ... aborting.');
        return;
    }
    const template = `import type { WebAPKifyConfig } from 'webapkify'

export default {
  // -- Identity --------------------------------------------------------------
  appName:     'My App',
  appId:       'com.example.myapp',
  versionCode: 1,
  versionName: '1.0.0',
  artifact:    'my-app',    // -> my-app-debug.apk / my-app-release.apk

  // -- Source ----------------------------------------------------------------
  webDir: './dist',         // your Vite / CRA / any SPA build output

  // -- SDK -------------------------------------------------------------------
  minSdk:            26,
  compileSdk:        35,
  targetSdk:         35,
  buildToolsVersion: '35.0.0',

  // -- Icons -----------------------------------------------------------------
  icon:                   './icon.png',      // 1024×1024 recommended
  adaptiveIconForeground: './icon-fg.png',   // 108dp canvas (optional)
  monochromeIcon:         './icon-mono.png', // Android 13+ themed icons (flat/grayscale)
  adaptiveIconBackground: '#FFFFFF',

  // -- App -------------------------------------------------------------------
  orientation:         'unspecified',
  statusBar:           'default',
  themeColor:          '#FFFFFF',
  backgroundColor:     '#FFFFFF',
  allowBackup:         true,
  hardwareAccelerated: true,
  keepScreenOn:        false,
  supportsRtl:         false,

  // clearTextDomains: ['localhost'],
  // allowAllClearText: false,

  // -- WebView ---------------------------------------------------------------
  webview: {
    javaScriptEnabled:                     true,
    javaScriptCanOpenWindowsAutomatically: false,
    domStorageEnabled:                     true,
    databaseEnabled:                       false,
    geolocationEnabled:                    false,
    allowMixedContent:                     false,
    builtInZoomControls:                   true,
    displayZoomControls:                   false,
    // userAgentString:                    'MyApp/1.0',
    allowFileAccessFromFileURLs:           false,
    allowUniversalAccessFromFileURLs:      false,
    textZoom:                              100,
    loadsImagesAutomatically:              true,
    blockNetworkImage:                     false,
    blockNetworkLoads:                     false,
    cacheMode:                             'DEFAULT',
    loadWithOverviewMode:                  false,
    useWideViewPort:                       true,
    mediaPlaybackRequiresUserGesture:      true,
    safeBrowsingEnabled:                   true,
    forceDark:                             'AUTO',
    algorithmicDarkeningAllowed:           false,
    acceptCookies:                         true,
    acceptThirdPartyCookies:               false,
  },

  // -- Permissions -----------------------------------------------------------
  permissions: {
    internet:     true,
    networkState: true,
    // camera:       false,
    // fineLocation: false,
    // postNotifications: false,
  },

  // -- Signing ---------------------------------------------------------------
  // signing: {
  //   storeFile:     './release.jks',
  //   storePassword: 'storePass',
  //   keyAlias:      'keyAlias',
  //   keyPassword:   'keyPass',
  //   v1SigningEnabled: true,
  //   v2SigningEnabled: true,
  //   v3SigningEnabled: true,
  // },

  // -- Build -----------------------------------------------------------------
  build: {
    minifyEnabled:   false,
    shrinkResources: false,
    jvmTarget:       '17',
    kotlinVersion:   '2.0.21',
    agpVersion:      '8.7.3',
    // extraProperties: { MY_API_KEY: 'abc123' },
  },
} satisfies WebAPKifyConfig`;
    fs.writeFileSync(destination, template);
    log.success('Created webapkify.config.ts');
    log.dim('Edit it, then run: webapkify build');
}
